/* CSS PART 2 OF 4 */

/* ========================================
   TRUST & COMPANY INTRODUCTION
======================================== */

.trust-strip {
  background: var(--white);
  border-bottom: 1px solid var(--line);
}

.trust-inner {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-items: center;
  padding-block: 28px;
}

.trust-item {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding-inline: 20px;
  border-right: 1px solid var(--line);
}

.trust-item:last-child {
  border-right: 0;
}

.trust-number {
  color: var(--amber-dark);
  font-family: var(--font-heading);
  font-size: 2.25rem;
  line-height: 1;
}

.trust-label {
  color: var(--ink-soft);
  font-size: 0.8rem;
  font-weight: 700;
  line-height: 1.45;
}

.about-layout {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: center;
  gap: clamp(45px, 8vw, 105px);
}

.about-visual {
  position: relative;
  min-height: 510px;
}

.about-image {
  width: 100%;
  height: 510px;
  border-radius: var(--radius-lg);
  object-fit: cover;
}

.about-caption {
  position: absolute;
  right: -22px;
  bottom: 28px;
  max-width: 230px;
  padding: 20px 24px;
  background: var(--forest);
  color: var(--white);
  border-bottom: 3px solid var(--amber);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow);
}

.about-caption strong {
  display: block;
  color: var(--amber);
  font-family: var(--font-heading);
  font-size: 1.55rem;
  font-weight: 400;
}

.about-caption span {
  display: block;
  margin-top: 5px;
  font-size: 0.8rem;
  line-height: 1.5;
}

.about-content h2 {
  margin-bottom: 24px;
}

.about-content > p {
  color: var(--ink-soft);
}

.about-points {
  display: grid;
  gap: 18px;
  margin-top: 30px;
}

.about-point {
  display: flex;
  align-items: flex-start;
  gap: 15px;
}

.about-point-icon {
  display: grid;
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  place-items: center;
  background: #eee9dc;
  border-radius: 50%;
  color: var(--amber-dark);
  font-weight: 800;
}

.about-point strong {
  display: block;
  margin-bottom: 3px;
  color: var(--forest-deep);
  font-size: 0.94rem;
}

.about-point p {
  color: var(--muted);
  font-size: 0.86rem;
  line-height: 1.65;
}

/* ========================================
   SERVICES
======================================== */

.services-section {
  background: #eeede6;
}

.services-layout {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  align-items: start;
  gap: 75px;
}

.services-intro {
  position: sticky;
  top: 40px;
}

.services-intro h2 {
  margin-bottom: 22px;
}

.services-intro p {
  color: var(--ink-soft);
}

.services-list {
  border-top: 1px solid #cfd1c7;
}

.service-item {
  display: grid;
  grid-template-columns: 55px 1fr auto;
  align-items: center;
  gap: 20px;
  padding-block: 27px;
  border-bottom: 1px solid #cfd1c7;
}

.service-number {
  color: var(--amber-dark);
  font-family: var(--font-heading);
  font-size: 1.5rem;
}

.service-item h3 {
  margin-bottom: 7px;
  font-size: 1.55rem;
}

.service-item p {
  max-width: 460px;
  color: var(--muted);
  font-size: 0.88rem;
  line-height: 1.65;
}

.service-arrow {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border: 1px solid #c6c9be;
  border-radius: 50%;
  color: var(--forest);
  font-size: 1.2rem;
}

/* ========================================
   ROOF ATTENTION / EDUCATIONAL CONTENT
======================================== */

.roof-section {
  background: var(--forest);
  color: var(--white);
}

.roof-layout {
  display: grid;
  grid-template-columns: 1fr 0.9fr;
  align-items: center;
  gap: clamp(45px, 8vw, 95px);
}

.roof-content h2 {
  margin-bottom: 22px;
  color: var(--white);
}

.roof-content > p {
  color: #d4ded8;
}

.roof-signs {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0 25px;
  margin-top: 32px;
}

.roof-sign {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding-block: 15px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.17);
  color: #f1f3ed;
  font-size: 0.88rem;
}

.roof-sign::before {
  color: var(--amber);
  content: "◆";
  font-size: 0.65rem;
  margin-top: 5px;
}

.roof-visual {
  position: relative;
}

.roof-image {
  width: 100%;
  height: 480px;
  border-radius: var(--radius-lg);
  object-fit: cover;
  object-position: center;
}

.roof-image-caption {
  position: absolute;
  right: 20px;
  bottom: 20px;
  left: 20px;
  padding: 18px 20px;
  background: rgba(25, 45, 42, 0.92);
  border-left: 3px solid var(--amber);
  color: var(--white);
  font-size: 0.85rem;
}

/* ========================================
   COLORADO ROOFING PROCESS
======================================== */

.process-section {
  background: var(--paper);
}

.process-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 40px;
  margin-bottom: 60px;
}

.process-heading .section-heading {
  margin-bottom: 0;
}

.process-heading > p {
  max-width: 340px;
  color: var(--muted);
  font-size: 0.9rem;
}

.process-steps {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.process-step {
  position: relative;
  min-height: 240px;
  padding: 30px 25px 35px 0;
}

.process-step:not(:last-child) {
  margin-right: 25px;
  border-right: 1px solid var(--line);
}

.process-step-number {
  display: inline-block;
  margin-bottom: 26px;
  color: var(--amber-dark);
  font-family: var(--font-heading);
  font-size: 2rem;
  line-height: 1;
}

.process-step h3 {
  margin-bottom: 12px;
  font-size: 1.35rem;
}

.process-step p {
  color: var(--muted);
  font-size: 0.85rem;
  line-height: 1.75;
}

/* ========================================
   RECENT PROJECTS / GALLERY
======================================== */

.projects-section {
  background: var(--white);
}

.projects-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 35px;
  margin-bottom: 48px;
}

.projects-heading .section-heading {
  margin-bottom: 0;
}

.projects-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  grid-template-rows: 290px 290px;
  gap: 20px;
}

.project-card {
  position: relative;
  overflow: hidden;
  min-width: 0;
  background: var(--forest);
  border-radius: var(--radius-md);
  isolation: isolate;
}

.project-card:first-child {
  grid-row: span 2;
}

.project-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 500ms ease;
}

.project-card:hover img {
  transform: scale(1.035);
}

.project-card::after {
  position: absolute;
  z-index: 1;
  inset: 35% 0 0;
  background: linear-gradient(
    to bottom,
    transparent,
    rgba(20, 35, 32, 0.85)
  );
  content: "";
  pointer-events: none;
}

.project-caption {
  position: absolute;
  z-index: 2;
  right: 25px;
  bottom: 24px;
  left: 25px;
  color: var(--white);
}

.project-caption span {
  display: block;
  margin-bottom: 7px;
  color: #f0c47d;
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.project-caption h3 {
  color: var(--white);
  font-size: 1.5rem;
}

.project-caption p {
  margin-top: 5px;
  color: #e0e7e1;
  font-size: 0.8rem;
}

.projects-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  margin-top: 35px;
  padding-top: 25px;
  border-top: 1px solid var(--line);
}

.projects-footer p {
  max-width: 520px;
  color: var(--muted);
  font-size: 0.88rem;
}
