/* CSS PART 3 OF 4 */

/* ========================================
   CONTACT / ESTIMATE CONVERSION SECTION
======================================== */

.contact-section {
  position: relative;
  overflow: hidden;
  background: var(--forest-deep);
  color: var(--white);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: clamp(55px, 8vw, 110px);
}

.contact-content {
  padding-top: 22px;
}

.contact-content h2 {
  margin-bottom: 24px;
  color: var(--white);
}

.contact-content > p {
  max-width: 470px;
  color: #d0dad3;
}

.contact-details {
  display: grid;
  gap: 22px;
  margin-top: 38px;
}

.contact-detail {
  display: flex;
  align-items: center;
  gap: 16px;
}

.contact-detail-icon {
  display: grid;
  width: 46px;
  height: 46px;
  flex-shrink: 0;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: var(--radius-sm);
  color: var(--amber);
  font-size: 1.2rem;
}

.contact-detail-copy {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.contact-detail-copy span {
  color: #b8c6bd;
  font-size: 0.73rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.contact-detail-copy a {
  color: var(--white);
  font-size: 1rem;
  font-weight: 700;
  transition: color var(--transition);
}

.contact-detail-copy a:hover {
  color: var(--amber);
}

.contact-direct-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 34px;
}

.contact-direct-actions .button {
  min-height: 49px;
  font-size: 0.82rem;
}

.contact-form-wrap {
  padding: clamp(28px, 4vw, 48px);
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow);
  color: var(--ink);
}

.contact-form-heading {
  margin-bottom: 30px;
}

.contact-form-heading h3 {
  margin-bottom: 9px;
  color: var(--forest-deep);
  font-size: 2rem;
}

.contact-form-heading p {
  color: var(--muted);
  font-size: 0.88rem;
}

.contact-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 21px 18px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
